// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz parameters: an address for the callee helper (not used directly), a bytes32 salt to build variable-length arrays,
    // and a uint8 len to determine array length. We let the fuzzer pick lengths and contents.
    function testFuzz_property(address unused, bytes32 seed, uint8 len) public {
        // keep length in a reasonable range but allow 1..64 (must be non-empty to exercise behavior)
        uint256 n = uint256(bound(len, 1, 64));

        // deploy a recording helper that exposes the exact function selector "transferFrom(address,address,uint256)"
        // so that c's low-level call via abi.encodeWithSelector will decode and be recorded.
        Recorder r = new Recorder();

        // build an array of addresses of length n with pseudorandom contents derived from seed
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            // derive an address pseudo-randomly from seed and index
            bytes32 h = keccak256(abi.encodePacked(seed, i));
            tos[i] = address(uint160(uint256(h)));
        }

        // call transfer. The Recording helper always returns true (succeeds) so both reference and mutant won't revert here.
        // We call from an arbitrary address (prank) to match realistic caller.
        address caller = address(0xBEEF);
        vm.prank(caller);
        bool ok;
        try c.transfer(caller, address(r), tos, 123) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference C always returns true (does not revert) for non-empty _tos when callee calls succeed,
        // so ok must be true for all admissible inputs. Mutant may also not revert but will make fewer calls.
        assertTrue(ok);

        // Now assert the universal property we observe: the recorder must have observed exactly n calls.
        // This is the key invariant: for any non-empty tos, C should call transferFrom exactly tos.length times.
        assertTrue(r.callCount() == n);
    }
}

// Recorder matches the selector used by C: transferFrom(address,address,uint256)
contract Recorder {
    // store number of times called and a mapping of index->decoded args to be inspectable
    uint public calls;
    struct Rec { address from; address to; uint256 v; }
    mapping(uint => Rec) public recs;

    // function with exact signature so that abi.decode in the target call is applied
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        recs[calls] = Rec({ from: from, to: to, v: v });
        calls++;
        return true;
    }

    // getter for call count (public variable provides getter but include explicit for clarity)
    function callCount() external view returns (uint) { return calls; }
}
